    pTVar1 = this->tFullList.m_terminator.m_prevlink;
    ppBucketSlot->m_prevlink = pTVar1;
    ppBucketSlot->m_next = pTVar1->m_next;
    pTVar1->m_next = (int)pNewEntry;
    this->tFullList.m_terminator.m_prevlink = ppBucketSlot;
